with base as (select *, lower(full_name) as full_name_lower from employees where salary < 105000 and (full_name like '%Chaiyap%' or level not in ('L4', 'L3'))), employees_stats as (select is_remote, job_title, concat_ws(', ', sort_array(collect_set(job_title))) as job_title_values, round(stddev(salary), 2) as stddev_salary from base group by is_remote, job_title) select is_remote, job_title, job_title_values, stddev_salary from employees_stats order by stddev_salary desc, job_title_values, is_remote, job_title limit 5
